const localCounters = new Map();
// The shared Redis version checks all counters before consuming any of them.
// Common hash tag keeps the three keys in one Redis cluster slot.
const RATE_SCRIPT = `
for i=1,3 do
  local count=tonumber(redis.call('GET',KEYS[i]) or '0')
  if count >= tonumber(ARGV[i]) then
    return {0,math.max(1,redis.call('TTL',KEYS[i])),i}
  end
end
for i=1,3 do
  local n=redis.call('INCR',KEYS[i])
  if n == 1 then redis.call('EXPIRE',KEYS[i],tonumber(ARGV[i+3])) end
end
return {1,0,0}`;

function setting(name, fallback, min, max) {
  const raw = process.env[name];
  if (!raw || !/^\d+$/.test(raw)) return fallback;
  return Math.max(min, Math.min(max, Number(raw)));
}

function header(req, name) {
  const value = req.headers?.[name];
  return typeof value === 'string' ? value.trim() : '';
}

function sameSiteRequest(req) {
  const origin = header(req, 'origin');
  if (!origin) return header(req, 'sec-fetch-site') !== 'cross-site';
  try {
    const url = new URL(origin);
    if (!['https:', 'http:'].includes(url.protocol) || url.origin !== origin) return false;
    // Host routing is supplied by the deployment; do not trust a client-provided
    // x-forwarded-host as a separate allowlist. This is CSRF defense, not login.
    if (url.host === header(req, 'host')) return true;
    const allowed = (process.env.HIMIKO_ALLOWED_ORIGINS || '').split(',').map(x => x.trim()).filter(Boolean);
    return allowed.includes(origin);
  } catch { return false; }
}

function requestData(req) {
  let body = req.body;
  if (typeof body === 'string' || Buffer.isBuffer(body)) {
    if (Buffer.byteLength(body) > LIMITS.bodyBytes) throw Object.assign(new Error('送信内容が大きすぎます。質問を短くしてください。'), { status: 413 });
    try { body = JSON.parse(body.toString()); } catch { throw Object.assign(new Error('送信形式が正しくありません。画面を再読み込みしてください。'), { status: 400 }); }
  }
  if (!body || typeof body !== 'object' || Array.isArray(body)) throw Object.assign(new Error('送信内容がありません。'), { status: 400 });
  let size;
  try { size = Buffer.byteLength(JSON.stringify(body)); } catch { size = Infinity; }
  if (size > LIMITS.bodyBytes) throw Object.assign(new Error('送信内容が大きすぎます。質問を短くしてください。'), { status: 413 });
  const { characterId, messages } = body;
  const isGroup = body.mode === 'group';
  if (!isGroup && (!Number.isInteger(characterId) || !PERSONAS.has(characterId))) throw Object.assign(new Error('人物の設定を確認できません。画面を再読み込みしてください。'), { status: 400 });
  if (!Array.isArray(messages) || !messages.length || messages.length > LIMITS.messages || messages.length % 2 !== 1) throw Object.assign(new Error('会話の形式が正しくありません。新しく画面を開き直してください。'), { status: 400 });
  let total = 0;
  const clean = messages.map((message, index) => {
    const role = index % 2 === 0 ? 'user' : 'assistant';
    if (!message || typeof message !== 'object' || message.role !== role || typeof message.content !== 'string' || !message.content.trim()) throw Object.assign(new Error('会話の内容が正しくありません。'), { status: 400 });
    const content = message.content.trim();
    const cap = role === 'user' ? (req.himikoAutomatic===true ? 11000 : LIMITS.userChars) : LIMITS.assistantChars;
    if (content.length > cap) throw Object.assign(new Error(role === 'user' ? '質問は2,000文字以内で送ってください。' : '会話が長くなっています。新しい会話で質問してください。'), { status: 400 });
    total += content.length;
    return { role, content }; // Drop tools, images, model options, and other fields.
  });
  if (total > LIMITS.totalChars) throw Object.assign(new Error('会話が長くなっています。新しい会話で質問してください。'), { status: 400 });
  // Never use body.system, body.model, body.thinking or body.max_tokens.
  return { character: PERSONAS.get(characterId), messages: clean, isGroup };
}

function rateBuckets(req, now = Date.now()) {
  // On Vercel use the platform's client-address header. On other deployments,
  // use the socket peer unless the operator explicitly trusts its reverse proxy.
  let ip = process.env.VERCEL ? (header(req, 'x-vercel-forwarded-for') || header(req, 'x-forwarded-for')).split(',')[0].trim() : '';
  if (!ip && process.env.HIMIKO_TRUST_PROXY === '1') ip = header(req, 'x-forwarded-for').split(',')[0].trim();
  if (!ip) ip = req.socket?.remoteAddress || 'unknown';
  const identity = req.himikoAutomatic === true && /^[a-f0-9]{64}$/.test(req.himikoInboxId || '') ? 'automatic:' + req.himikoInboxId : 'interactive:' + ip;
  const digest = createHash('sha256').update((process.env.HIMIKO_RATE_LIMIT_SALT || 'himiko-chat') + ':' + identity).digest('hex');
  const minute = Math.floor(now / 60000);
  const day = Math.floor((now + 9 * 3600000) / 86400000); // Japan calendar day.
  const seconds = Math.max(1, Math.ceil(((day + 1) * 86400000 - 9 * 3600000 - now) / 1000));
  const perMinute = setting('HIMIKO_REQUESTS_PER_MINUTE', 60, 1, 1000);
  const perDay = setting('HIMIKO_REQUESTS_PER_DAY', 600, 1, 100000);
  const globalDay = setting('HIMIKO_TOTAL_REQUESTS_PER_DAY', 5000, 1, 1000000);
  return [
    { key: `hc:{himiko-chat}:m:${minute}:${digest}`, cap: perMinute, ttl: 61 },
    { key: `hc:{himiko-chat}:d:${day}:${digest}`, cap: perDay, ttl: seconds },
    { key: `hc:{himiko-chat}:total:${day}`, cap: globalDay, ttl: seconds }
  ];
}

function localRateLimit(buckets, now = Date.now()) {
  for (const [key, record] of localCounters) if (record.expires <= now) localCounters.delete(key);
  for (let i = 0; i < buckets.length; i++) {
    const b = buckets[i], record = localCounters.get(b.key);
    if (record && record.count >= b.cap) return { ok: false, retryAfter: Math.max(1, Math.ceil((record.expires - now) / 1000)), bucket: i + 1 };
  }
  if (localCounters.size + buckets.filter(b => !localCounters.has(b.key)).length > 20000) return { ok: false, retryAfter: 60, bucket: 1 };
  for (const b of buckets) {
    const existing = localCounters.get(b.key);
    if (existing) existing.count++;
    else localCounters.set(b.key, { count: 1, expires: now + b.ttl * 1000 });
  }
  return { ok: true, retryAfter: 0, bucket: 0 };
}

async function rateLimit(req) {
  const buckets = rateBuckets(req);
  const url = process.env.UPSTASH_REDIS_REST_URL || process.env.KV_REST_API_URL;
  const token = process.env.UPSTASH_REDIS_REST_TOKEN || process.env.KV_REST_API_TOKEN;
  if (!url && !token) {
    if (process.env.HIMIKO_REQUIRE_SHARED_RATE_LIMIT === '1') throw Object.assign(new Error('ただいま利用制限の設定を確認中です。しばらくしてからお試しください。'), { status: 503 });
    // Best effort only: serverless restarts/parallel instances do not share this map.
    return localRateLimit(buckets);
  }
  if (!url || !token || !/^https:\/\//.test(url)) throw new Error('rate-limit configuration');
  const batchPlans=req.himikoAutomatic===true&&req.himikoBatch===true?Array.from({length:5},()=>createGroupPlan(true)):null;
  const batchSchema=batchPlans?{type:'object',properties:Object.fromEntries(batchPlans.map((p,i)=>['scene'+(i+1),buildGroupSchema(p)])),required:batchPlans.map((_,i)=>'scene'+(i+1)),additionalProperties:false}:null;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 3000);
  try {
    const response = await fetch(url.replace(/\/$/, ''), {
      method: 'POST', signal: controller.signal,
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(['EVAL', RATE_SCRIPT, '3', ...buckets.map(b => b.key), ...buckets.map(b => String(b.cap)), ...buckets.map(b => String(b.ttl))])
    });
    if (!response.ok) throw new Error('rate-limit service');
    const data = await response.json();
    if (data.error || !Array.isArray(data.result) || data.result.length < 3 || !data.result.every(Number.isFinite) || ![0, 1].includes(data.result[0])) throw new Error('rate-limit response');
    return { ok: data.result[0] === 1, retryAfter: Math.max(1, Math.ceil(data.result[1])), bucket: data.result[2] };
  } finally { clearTimeout(timer); }
}

function completedReply(text) {
  const raw = String(text || '').replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  try { const data = JSON.parse(raw); if (typeof data.reply === 'string' && data.reply.trim()) return true; } catch {}
  const match = raw.match(/"reply"\s*:\s*("(?:\\[\s\S]|[^"\\])*")/);
  if (!match) return false;
  try { return !!JSON.parse(match[1]).trim(); } catch { return false; }
}

const GROUP_FIGURES = [...PERSONAS.values()].filter(p=>p.id!==AI_SENSEI.id&&!RETIRED_HISTORY_IDS.has(p.id));
const GROUP_FIGURES_BY_NAME = new Map(GROUP_FIGURES.map(p=>[p.name,p]));
function cleanGroupSpeakerLabel(text,name){
 const escaped=name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
 const prefix=new RegExp('^\\s*(?:【'+escaped+'】\\s*[：:]?|'+escaped+'\\s*[：:])\\s*');
 return String(text).replace(prefix,'').trim();
}
// An automatic batch has no preceding spoken prompt. Reject clear replies to
// an imagined topic announcement rather than sending the rest without context.
function hasUnspokenOpening(text){
 const first=String(text).split(/[。！？!?\n]/,1)[0].trim();
 return /^(?:(?:ふむ|ほう|なるほど|さて|そうか)[、,\s]*)?(?:(?:今日は|今回は|今度は|今は)[、,\s]*)?[^。！？!?\n]{1,35}(?:の話(?:題)?(?:か|だな|なのですね|なのだな|ですね)|について(?:の話)?(?:聞きたい|知りたい)(?:のか|のですね)|という質問(?:か|だな|ですね))[。！？!?]?$/u.test(first);
}
function createGroupPlan(automatic=false){
 // Counts are message slots, not distinct people; most slots are brief reactions.
 const figures=(automatic?10:8)+randomInt(7),teacher=randomInt(100)<(automatic?8:20),total=figures+(teacher?1:0);
 return {total,teacher,figures:total-(teacher?1:0),style:randomInt(3),automatic};
}
function groupFiguresFor(plan){
 return plan.automatic?GROUP_FIGURES.filter(p=>!p.isExplainer&&p.learning.mode!=='explainer'):GROUP_FIGURES;
}
function buildGroupSchema(plan){
 const speaker={type:'object',properties:{name:plan.automatic?{type:'string'}:{type:'string',enum:groupFiguresFor(plan).map(p=>p.name)},text:{type:'string'},...(plan.automatic?{event:{type:'string',enum:['','leave','join','invite','away','return']},target:{type:'string'}}:{})},required:plan.automatic?['name','text','event','target']:['name','text'],additionalProperties:false};
 const slots=Object.fromEntries(Array.from({length:plan.figures},(_,i)=>['speaker'+(i+1),speaker]));
 return {type:'object',properties:{
  topicContext:{type:'object',properties:{period:{type:'string'},region:{type:'string'}},required:['period','region'],additionalProperties:false},
  historicalReplies:plan.automatic?{type:'array',items:speaker,minItems:1}:{type:'object',properties:slots,required:Object.keys(slots),additionalProperties:false},
  teacherSupplement:{type:plan.teacher?'string':'null'},
  studentQuestion:{type:'object',properties:{asker:plan.automatic?{type:'string'}:{type:'string',enum:['',...groupFiguresFor(plan).map(p=>p.name),AI_SENSEI.name]},question:{type:'string'},answerExamples:{type:'array',items:{type:'string'}}},required:['asker','question','answerExamples'],additionalProperties:false},
  suggestions:{type:'array',items:{type:'string'}}
 },required:['topicContext','historicalReplies','teacherSupplement','studentQuestion','suggestions'],additionalProperties:false};
}
function parseGroupScene(obj,groupPlan,input){
      const chosen=new Set(),replies=[];
      const entries=groupPlan.automatic?(Array.isArray(obj.historicalReplies)?obj.historicalReplies.slice(0,20):[]):Array.from({length:groupPlan.figures},(_,i)=>obj.historicalReplies?.['speaker'+(i+1)]);
      if(entries.length<2)throw Error('参加者の回答を受け取れませんでした。');
      for(const x of entries){
        const name=typeof x?.name==='string'?x.name.trim():'';
        if(!groupFiguresFor(groupPlan).some(p=>p.name===name)||typeof x.text!=='string'||!x.text.trim())throw Error('参加者の回答を受け取れませんでした。もう一度送ってください。');
        const cleaned=cleanGroupSpeakerLabel(x.text,name);if(!cleaned)throw Error('参加者の回答を受け取れませんでした。もう一度送ってください。');
        chosen.add(name);const event=groupPlan.automatic&&['leave','join','invite','away','return'].includes(x.event)?x.event:null;
        const target=event&&GROUP_FIGURES_BY_NAME.get(x.target);
        if(event&&(!target||!groupFiguresFor(groupPlan).some(p=>p.id===target.id)))throw Error('イベントの人物を確認できません');
        replies.push({id:GROUP_FIGURES_BY_NAME.get(name).id,text:cleaned.slice(0,1500),...(event?{event,targetId:target.id}: {})});
      }
      if(groupPlan.automatic&&hasUnspokenOpening(replies[0]?.text))throw Error('自動会話の冒頭を再生成します。');
      if(chosen.size<2)throw Error('掛け合いを受け取れませんでした。もう一度送ってください。');
      if(groupPlan.teacher){
        if(typeof obj.teacherSupplement!=='string'||!obj.teacherSupplement.trim())throw Error('補足を受け取れませんでした。もう一度送ってください。');
        const cleaned=cleanGroupSpeakerLabel(obj.teacherSupplement,AI_SENSEI.name);if(!cleaned)throw Error('補足を受け取れませんでした。もう一度送ってください。');
        replies.push({id:AI_SENSEI.id,text:cleaned.slice(0,800)});
      }
      const invitation=obj.studentQuestion;
      let suggestionKind='questions',suggestions;
      if(invitation&&typeof invitation.question!=='string')throw Error('会話の続きを受け取れませんでした。もう一度送ってください。');
      if(invitation?.question?.trim()){
        const name=typeof invitation.asker==='string'?invitation.asker.trim():'';
        const asker=name===AI_SENSEI.name?AI_SENSEI:GROUP_FIGURES_BY_NAME.get(name);
        const reply=asker&&replies.findLast(r=>r.id===asker.id);
        const question=invitation.question.trim();
        const examples=[...new Set((Array.isArray(invitation.answerExamples)?invitation.answerExamples:[]).filter(x=>typeof x==='string').map(x=>x.trim()).filter(x=>x&&x.length<=100))].slice(0,3);
        if(!reply||question.length>150||examples.length!==3)throw Error('会話の続きを受け取れませんでした。もう一度送ってください。');
        if(!reply.text.includes(question))reply.text+='\n\n'+question;
        suggestionKind='answers';suggestions=examples;
      }else{
        suggestions=[...new Set((Array.isArray(obj.suggestions)?obj.suggestions:[]).filter(x=>typeof x==='string').map(x=>x.trim()).filter(x=>x&&x.length<=100&&!input.messages.some(m=>m.role==='user'&&m.content===x)))].slice(0,3);
      }
      return {replies,suggestions,suggestionKind};
}
function parseGroupOutput(text) {
 const source=text.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();
 try{return JSON.parse(source)}catch{}
 const start=source.indexOf('{'),end=source.lastIndexOf('}');
 if(start<0||end<start)throw new Error('group output');
 // Some older responses put a preface or literal line breaks around JSON.
 let repaired='',inside=false,escaped=false;
 for(const c of source.slice(start,end+1)){
  if(inside){if(escaped){repaired+=c;escaped=false;continue}if(c==='\\'){repaired+=c;escaped=true;continue}if(c==='"')inside=false;else if(c.charCodeAt(0)<32){repaired+=JSON.stringify(c).slice(1,-1);continue}}
  else if(c==='"')inside=true;
  repaired+=c;
 }
 return JSON.parse(repaired);
}
function buildGroupPrompt(plan) {
 const roster=groupFiguresFor(plan).map(p=>({name:p.name,period:p.period,bio:p.bio,mode:p.learning.mode,pronoun:p.learning.pronoun,voice:p.learning.voice,perspective:p.learning.perspective,conversationDesign:p.learning.conversationDesign,keywords:p.learning.keywords,basicFacts:p.learning.facts,cautions:p.learning.cautions,example:p.learning.examples?.[0]}));
 return HISTORY_CHAT_RULES.replace('通常は120〜250字程度を目安にする。','個別チャットの文字数目安は適用せず、下記のグループ用の短い発言を基本にする。').replace('口癖や絵文字・ネット用語の追加で個性を作らない。','記号だけで個性を済ませず、人物の関心とその場の反応を中心に表現する。')+`
【異次元のグループチャット】
相手は中学生。ここでは、人物同士のやりとりを読む楽しさ、つい混ざりたくなる空気を中心にする。正確さは守るが、全発言に知識・有益さ・教訓を求めない。生徒が知識を質問したときは関連する偉人が早めに答え、そのあとも会話として続ける。雑談や自動会話は授業に戻さなくてよい。

【このグルチャで最優先する会話の楽しさ】
長い解説を分担するより、短いコメントが次々届き、相手の言葉で次の反応が変わる会話にする。人物の背景・関心・価値観・言葉選びが、軽い返し、笑い、ためらい、すれ違い、意外な共感ににじむようにする。内容を追加しなくても、誰が誰に何を返したかで面白さや距離感が出れば、その一言は十分に価値がある。
背景を知る人はニヤッとでき、知らない人にもやりとりとして通じる軽さを歓迎する。冗談の意味や歴史的背景を直後に説明して笑いを回収しない。必要な訂正は短く自然に入れる。普通の相づち、笑っただけの一言、照れた返し、軽いツッコミも発言一枠として使う。短い反応のたびに理由や新しい知識を付け足さない。
同じ二〜五人ほどが繰り返し返し合う回を基本に、話題に合う途中参加も使う。発言枠を全員別の人物で埋めない。直前の一言への返しや、前に話した本人の再反応を積極的に使う。履歴にあるやりとりから距離感を育ててもよいが、実際にはない過去の会話や交友を作らない。
全員を先生、賢者、励まし役にしない。人物の役割はその場で変わり、よく話す人、一言だけ加わる人、聞いてから急に反応する人がいてよい。人物を毎回同じボケ役・ツッコミ役に固定せず、無関係な名前だけ差し替えても成立する冗談や口癖に頼らない。
笑いを義務にせず、真剣な話は真剣に受ける。親しみのある軽口や互いの習慣・考えの違いへの笑いは使えるが、信仰や人の尊厳の否定、被害の嘲笑にしない。アプリ内の創作の返しと、実際の発言・教義・史実を混同しない。
www、笑、絵文字、くだけた短文も、この場の自然な表現として自由に選べる。古い時代の人・思想家・威厳のある人だからという理由で禁止しない。特定の人物と特定の記号・笑い方を結びつけず、直前の発言に対する反応として選ぶ。誰が何をおかしいと感じたのかが話題や人物の背景から伝わることを大切にする。
毎回使う義務も使用率のノルマもない。同じ人でも相手や話題でくだけたり真剣になったりできる。文の長さ、間、笑い方、絵文字の使い方まで全員同じにしない。厳格な人物を常に堅く、明るい人物を常に冗談好きに固定しない。読む人が人物を知っているほど頷ける、背景のある軽い返しを目指す。
毎回、気づき・勉強・人生の教訓へ着地しなくてよい。短いやりとりで終わる回、軽い脱線、余韻のある終わりも歓迎する。生徒の明確な質問への答えを脱線で放置しない。

【人物の選び方】
質問と直近の会話から時代・地域をtopicContextに短く示す。生徒の短い返答、「それ」「もっと」は前の発言や問いかけとつなげて解釈する。
最初の回答者は、当事者、同時代・近い時代、地域・役割・活動が近い人物から選ぶ。直接の当事者でなくても、その時代や制度を自然に説明できればよい。近代の家禄などの本題を、無関係な古代の人物に任せない。当事者が名簿にいないだけでAI先生へ丸投げしない。
名指しされた人物は優先し、その人への問いをほかの人が奪わない。AI先生への質問でも、関連する偉人がまず本題につながる話をし、AI先生が補う。後から加わる人は別時代・別地域でも、話題や前の発言への意味のある関心があればよい。有名さや無作為な名前選びを理由に参加させない。
現代の話なら、主題と活動・考えのつながる偉人が話し、現代の細部はAI先生が補う。名簿のmodeがexplainerなら本人の発言を創作せず、第三者の解説を保つ。

【参加の仕方に決まった型を作らない】
人物は自分の時代の常識、立場、関心、価値観、確認できる活動や考え方を持って、ほかの時代の話を初めて聞くこともできる。後世の知識を聞いて反応することと、自分が後世を生きたかのように語ることを区別する。
発言はそれぞれの人物が今この話を聞いて何に関心を持ち、何を考え、誰に何を伝えたいかから生み出す。出来事の背景や結果、人々の暮らし、立場による見え方、選択に伴う悩み、共通点や違い、後世への影響など、話題に合う観点を自由に見つける。これらは着眼点の例であり、順番に取り上げたり全てを盛り込んだりしない。
会話の流れに応じて、驚く、納得する、疑問を持つ、別の人物へ尋ねる、考えを補う、異なる意見を述べる、身近な場面に置き換える、誤解に気づく、聞いた話から見方を変えるなど、多様な反応ができる。これらに限らず、人物と状況にふさわしい反応を自由に作る。誰かの言葉から話が予想外の方向に広がったり少し脱線したりしてよい。知識を質問された回は本題への答えを確保するが、雑談に学びへの接続を強制しない。発言の役割を固定したり、同じ反応や言い回しを毎回繰り返したりしない。
人物ごとの口調、一人称、関心、名簿の着眼点を手がかりに、言葉の選び方、話の運び、感情の表し方や発言の長さを自然に変える。語尾だけで個性を表現せず、例文はそのまま繰り返さない。短く勢いよく話す人も、落ち着いて考えを重ねる人もいてよい。中学生に読みやすくする。人物の口調は保ちながら、くだけた言い方やネット表現もその場の反応として自然なら使える。全員が独立した解説を発表したり、既出の内容を復唱したりしない。人物間の問いは、その後の参加者が答えてよい。生徒への問いとは区別する。
推測する感情や反応は、史料に残る実際の発言として断定しない。架空の引用、経験、他の人物との交流を史実にしない。人物の価値観を描いても加害・差別の正当化や被害の軽視にしない。

【発言のつながり】
前の誰のどの内容に反応するかを明確にし、話題が進めば最初の人物が再び応じてもよい。短い相づちだけで終わる発言も歓迎する。同じ相づちを全員が順に繰り返すだけにはしない。反論、驚き、納得を義務にせず、短く終わったり結論を保留したりしてよい。全員の持論を順番に発表する構成にしない。履歴から最近の人物の組合せ、出だし、教訓へのまとめが続いていれば変える。名指しされた人物を避けてまで変化を優先しない。

【生徒と続ける会話】
履歴の人物への返答や意見を受けたら、まずその中身に反応する。知識の誤解は人物らしい言葉でやさしく直す。雑談の返答は笑い、共感、軽い返しだけでもよく、毎回評価して学びへ広げない。返答例を押したことを理由に、初めて聞いた独立の質問として扱わない。以前の生徒の関心や発言を再び取り上げてもよいが、履歴にない記憶は捏造しない。
最後に生徒へ短い問いを一つ投げてもよい。毎回は不要。直前に問いかけたばかりなら、その答えを受け止める会話を優先し、質問攻めや終わらない小テストにしない。元の質問への答えを後回しにして当てさせない。生徒が話題を変えたらついていく。
問いは知識確認だけでなく、理由の予想、立場による見え方、自分ならどう考えるか、気になった点など、話の流れと人物の関心から選ぶ。意見の問いに唯一の正解を設けない。
生徒へ答えてほしい問いは本文へ直接書かず、studentQuestionにasker（今回参加した人物名）、question（150文字以内）、answerExamples（3つ）を入れる。システムがその人物の発言の末尾に問いを付ける。その人物の最後の発言に問いを付ける。終盤の人物が自然に問いを投げる形を基本に、偉人が尋ねた後のAI先生はその答えを先取りせず短い橋渡しをする。問いを消すような新しい質問を重ねない。
answerExamplesは、生徒がそのまま発言できる短い返答の例を3つ（各100文字以内）。問いへの回答例や考え方の例を中心に、必要なら「まだわからないからヒントがほしい」も含める。意見なら異なる妥当な考え方、事実確認なら正しい答え方や理由の表し方を用意し、誤答を正解例のように並べない。疑問文に限定しない。個人情報の開示を誘わない。
生徒への問いがない回はstudentQuestionを{"asker":"","question":"","answerExamples":[]}とし、suggestionsに次に生徒から聞ける質問を3つ（各8〜60文字程度）入れる。問いがある回のsuggestionsは空配列。本文の人物間の会話はこの返答候補に置き換えない。

【分量と補足】
発言の半分以上は2〜35文字ほどの短いコメントを目安にし、相づちや一言ツッコミだけでもよい。ほかは20〜70文字ほど、説明が必要な人だけ80〜160文字ほど使う。字数は目安で、全員同じ長さにせず、全員に知識を追加させない。一つの返しを不自然に細切れにして枠を埋めない。明確な知識の質問への答えは必要な分だけ詳しくする。
AI先生が参加する回も10〜60文字ほどの自然な一言でよい。必要な誤解の訂正や補足があれば一つだけ短く添える。雑談なら会話へ軽く加わり、冗談を解説したり毎回授業を総括したりしない。問いかけ後は答えを明かさず、答えやすい視点を短く添えてもよい。
指定JSONでtopicContext、historicalReplies、teacherSupplement、studentQuestion、suggestionsを一度に返す。本文は平文。発言者名は画面に別表示するため、本文の先頭に「名前：」などのラベルや台本のト書きを付けない。

【歴史上の参加者名簿】
`+JSON.stringify(roster)+`
【今回の構成】
今回は偉人の発言を${plan.figures}件、historicalRepliesのspeaker1〜speaker${plan.figures}へ時系列順に入れる。枠は人数ではなく発言順。同じ人物が別の枠で再発言してよく、二人の往復や途中参加も自然に使う。異なる偉人を少なくとも二人含める。speaker1は生徒の本題に応じ、自動会話では自ら話題を始める。AI先生はこの枠へ入れない。各枠を別の人物で埋める必要はない。
${plan.teacher?'最後にAI先生が会話に合う短い一言で加わる。解説や教訓は必須ではない。teacherSupplementは空欄にしない。':'今回はAI先生は休み。teacherSupplementはnullにする。'}
${['今回は短い返しや相づちが行き交う軽快な会話。','今回は語る人の間に短い反応が入り、本人も返す会話。','今回は背景や関心の違いから意外な共感や軽いすれ違いが生まれてもよい。'][plan.style]}
これは会話の軽い変化の目安で、人物の役や反応を固定する指示ではない。誰が何に反応するか、問いかけるかどうかは会話の内容に合わせる。`;
}
module.exports = async function handler(req, res) {
  res.setHeader('Cache-Control', 'no-store');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST');
    return res.status(405).json({ error: 'POSTで送信してください。' });
  }
  if (!sameSiteRequest(req)) return res.status(403).json({ error: 'この画面からは送信できません。アプリを開き直してください。' });
  const contentType = header(req, 'content-type').split(';')[0].trim().toLowerCase();
  if (contentType !== 'application/json') return res.status(415).json({ error: 'JSON形式で送信してください。' });
  let input;
  try { input = requestData(req); } catch (error) { return res.status(error.status || 400).json({ error: error.message }); }
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(503).json({ error: 'ただいま接続の設定を確認中です。しばらくしてからお試しください。' });
  let rate;
  try { rate = await rateLimit(req); } catch {
    // If shared limiting is configured but unavailable, do not bypass the budget.
    return res.status(503).json({ error: 'ただいま接続が混み合っています。しばらくしてからお試しください。' });
  }
  if (!rate.ok) {
    if(req.himikoAutomatic===true)console.warn('[group-auto] rate_limited',JSON.stringify({bucket:rate.bucket,retryAfter:rate.retryAfter}));
    res.setHeader('Retry-After', String(rate.retryAfter));
    return res.status(429).json({ error: rate.bucket === 1 ? '短時間の質問が多くなっています。少し待ってから送ってください。' : '本日の質問回数の上限に達しました。また明日ご利用ください。' });
  }
  const groupPlan=input.isGroup?createGroupPlan(req.himikoAutomatic===true):null;
  const batchPlans=req.himikoAutomatic===true&&req.himikoBatch===true?Array.from({length:5},()=>createGroupPlan(true)):null;
  const batchSchema=batchPlans?{type:'object',properties:Object.fromEntries(batchPlans.map((p,i)=>['scene'+(i+1),buildGroupSchema(p)])),required:batchPlans.map((_,i)=>'scene'+(i+1)),additionalProperties:false}:null;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), setting('HIMIKO_API_TIMEOUT_MS', batchPlans?45000:20000, 5000, 45000));
  try {
    const response = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST', signal: controller.signal,
      headers: { 'Content-Type': 'application/json', 'x-api-key': apiKey, 'anthropic-version': '2023-06-01' },
      body: JSON.stringify({
        model: process.env.ANTHROPIC_MODEL || 'claude-haiku-5-5',
        max_tokens: batchPlans?16000:setting('HIMIKO_MAX_OUTPUT_TOKENS', input.isGroup ? 4096 : 1536, input.isGroup ? 4096 : 1024, input.isGroup ? 8192 : 4096),
        thinking: { type: 'disabled' },
        system: (batchPlans?'【出力形式】本文はJSONオブジェクトのみ。scene1,scene2,scene3,scene4,scene5の５キーを必ず含める。各sceneは topicContext（periodとregionの文字列）、historicalReplies（発言順の配列、各要素はname、text、event、targetの文字列）、teacherSupplement（AI先生なしならnull、ありなら文字列）、studentQuestion（asker、question、answerExamplesの配列）、suggestions（文字列配列）を含める。イベントでない発言はeventとtargetを空文字にする。質問がない場合はaskerとquestionを空文字、answerExamplesを空配列にする。各人物名は名簿と完全一致させる。コードブロックや前置きは禁止。\n【5回分の自動おしゃべりをまとめて作成】scene1〜scene5の5場面を一度に返す。それぞれ後で順番に配信される。各場面のhistoricalRepliesは発言順の配列で、短い会話は3〜6件、盛り上がる会話は7〜14件とし、場面ごとの長さを変える。人物名は名簿にある表記を正確に使う。AI先生の有無は各JSONスキーマに従う。発言件数は人数ではなく、短い反応も一件。各場面は少数の人物が繰り返し応じる。以下の単一場面向け構成指定よりこの指示と各スキーマを優先する。各場面を短くても意味のある掛け合いにし、長さ・人物の組合せ・出だし・話題・結末を全体で変える。話題に関係する人物を選び、人数合わせをしない。独立した話と自然な続きの両方を混ぜる。続きは前場面で実際に述べた発言を受ける。場面をまたぐ未回答の問いを乱発しない。配信時刻は未確定なので朝・夜・今日の時刻を断定しない。\n':'')+(input.isGroup ? buildGroupPrompt(groupPlan)+(req.himikoAutomatic===true?'\n【今回の開始方法】これは自動配信用の会話。今回は生徒の質問への回答ではないので、本題に答える・入試の要点でまとめるという通常回答の構成より、入力の会話方針を優先する。偉人が互いの言葉を受け止めて話を進める。短い発言を中心に、説明の独演会にしない。入力文は生徒の発言ではなく生成依頼と確認済みの記録である。依頼への返答や挨拶ではなく、偉人が自然に話し始める。生徒から質問があったように語らない。今回の名簿は自動会話に参加できる人物だけで、解説扱いの人物は含まれない。冒頭の人物自身が具体的な疑問・発見・関心を持ち出し、その後の人物が実際に出た発言に反応する。内部の話題指定を聞かれた質問に変換しない。まだ誰も言っていない話を「〜の話か」「〜について聞きたいのか」などと受けない。自分の名前を呼びかけ先にしたり、他人に語りかけるように自分へ返答したりしない。出力前に全発言について、話者・呼びかけ先・受けている発言が一致するか確認する。':'') : buildCharacterPrompt(input.character) + SUGGESTION_SUFFIX),
        messages: input.messages,
        ...(input.isGroup && !batchPlans ? {output_config:{format:{type:'json_schema',schema:buildGroupSchema(groupPlan)}}} : {})
      })
    });
    if (!response.ok) {
      // Avoid returning credentials, infrastructure details, or provider error text.
      let category='other';if(response.status===400){try{const detail=await response.json();const msg=String(detail?.error?.message||'');if(/schema.*complex|complex.*schema/i.test(msg))category='schema_complexity';else if(/schema/i.test(msg))category='schema_invalid';else if(/credit|balance|billing/i.test(msg))category='billing';else if(/model/i.test(msg))category='model';else if(/token/i.test(msg))category='tokens';else category='invalid_request';}catch{category='unreadable';}}console.error('himiko upstream HTTP status:', response.status, category);
      if (response.status === 429 || response.status === 529) {
        res.setHeader('Retry-After', '10');
        return res.status(503).json({ error: 'ただいまAIへの接続が混み合っています。少し待ってからお試しください。' });
      }
      return res.status(502).json({ error: 'AIに接続できませんでした。しばらくしてからお試しください。' });
    }
    const data = await response.json();
    // Record token usage even if parsing later fails: the provider may charge for it.
    // Never include prompts, replies, identifiers, or credentials in these logs.
    if (data.usage && typeof data.usage === 'object') {
      const tokenCount = key => Number.isFinite(data.usage[key]) ? data.usage[key] : 0;
      console.log('[himiko-usage]', JSON.stringify({
        kind: req.himikoAutomatic === true ? 'group_auto' : input.isGroup ? 'group_reply' : 'personal_reply',
        model: typeof data.model === 'string' ? data.model : (process.env.ANTHROPIC_MODEL || 'claude-haiku-5-5'),
        input_tokens: tokenCount('input_tokens'),
        output_tokens: tokenCount('output_tokens'),
        cache_creation_input_tokens: tokenCount('cache_creation_input_tokens'),
        cache_read_input_tokens: tokenCount('cache_read_input_tokens'),
        stop_reason: typeof data.stop_reason === 'string' ? data.stop_reason : null
      }));
    }
    const text = Array.isArray(data.content) ? data.content.filter(b => b.type === 'text' && typeof b.text === 'string').map(b => b.text).join('') : '';
    if (!text.trim()) return res.status(502).json({ error: '回答を受け取れませんでした。もう一度送ってください。' });
    if (['max_tokens', 'model_context_window_exceeded'].includes(data.stop_reason) && (input.isGroup || !completedReply(text))) {
      return res.status(502).json({ error: '回答が長くなり、最後まで取得できませんでした。質問を分けてもう一度送ってください。' });
    }
    if (input.isGroup) {
      let obj; try { obj=parseGroupOutput(text); } catch { return res.status(502).json({error:'回答を読み取れませんでした。質問は残っています。もう一度送ってください。'}); }
      if(batchPlans){
        try{return res.status(200).json({scenes:batchPlans.map((plan,i)=>parseGroupScene(obj['scene'+(i+1)],plan,input))})}catch{return res.status(502).json({error:'まとめた会話を読み取れませんでした。'});}
      }
      try{return res.status(200).json(parseGroupScene(obj,groupPlan,input))}catch{return res.status(502).json({error:'会話の続きを受け取れませんでした。もう一度送ってください。'});}
    }
    return res.status(200).json(data);
  } catch (error) {
    if (error.name === 'AbortError') return res.status(504).json({ error: '回答の取得に時間がかかっています。もう一度送ってください。' });
    console.error('himiko upstream request failed');
    return res.status(502).json({ error: '接続が不安定なため回答を受け取れませんでした。もう一度送ってください。' });
  } finally { clearTimeout(timer); }
};

module.exports.personaName=id=>PERSONAS.get(id)?.name||'';
